import React from 'react';
import { MessageSquare } from 'lucide-react';

export default function RotatingTextCircle() {
  return (
    <div className="relative flex items-center justify-center w-28 h-28 sm:w-32 sm:h-32 mx-auto">
      {/* Rotating SVG Text Circle */}
      <svg
        className="w-full h-full animate-spin-slow select-none pointer-events-none"
        viewBox="0 0 160 160"
      >
        <path
          id="circlePath"
          d="M 80, 80 m -60, 0 a 60,60 0 1,1 120,0 a 60,60 0 1,1 -120,0"
          fill="none"
        />
        <text className="text-[11px] font-bold fill-sky-800 tracking-[0.25em] uppercase">
          <textPath href="#circlePath" startOffset="0%">
            • CONNECT • PRIVATE • RELIABLE • SECURE • MESSAGING
          </textPath>
        </text>
      </svg>

      {/* Center Icon Badge */}
      <div className="absolute inset-0 m-auto w-14 h-14 rounded-2xl bg-white shadow-xl shadow-sky-900/10 border border-slate-100 flex items-center justify-center group-hover:scale-110 transition-transform duration-300">
        <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-[#006699] to-sky-500 flex items-center justify-center text-white shadow-md shadow-sky-600/20">
          <MessageSquare className="w-5 h-5 stroke-[2.5]" />
        </div>
      </div>
    </div>
  );
}
